// Serves the sitemap generated by the backend at /sitemap.xml.
// SITEMAP_SOURCE_URL overrides the default of `${NEXT_PUBLIC_API_BASE_URL}/sitemap.xml`.
export async function getServerSideProps({ res }) {
    const source = process.env.SITEMAP_SOURCE_URL || `${process.env.NEXT_PUBLIC_API_BASE_URL}/sitemap.xml`;

    try {
        const upstream = await fetch(source);
        if (!upstream.ok) throw new Error(`Sitemap upstream returned ${upstream.status}`);
        const xml = await upstream.text();
        res.setHeader('Content-Type', 'application/xml; charset=utf-8');
        res.setHeader('Cache-Control', 'public, s-maxage=3600, stale-while-revalidate=86400');
        res.write(xml);
    } catch {
        res.statusCode = 502;
    }
    res.end();
    return { props: {} };
}

export default function Sitemap() {
    return null;
}
